//! 🔺️ Original mesh reconstruction retains every typed buffer and scalar relationship frontier.
use super::{SemioMeshSnapshot,SemioMesh,SemioPrimitive,SemioTopology,SemioMaterial,SemioTexture,SemioPoint3,SemioUv,SemioRgba,identity,float_columns,tick};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{FloatRow,RowIndex,RowIndexStorage,reconstruct_text_into,reconstruct_blob_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioMeshSnapshot>,validation:SchemaValidationStorage,indices:[RowIndexStorage;9],orders:[Vec<usize>;9]}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),indices:std::array::from_fn(|_|RowIndexStorage::empty()),orders:std::array::from_fn(|_|Vec::new())}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn optional_into(destination:&mut Option<String>,row:FloatRow<'_>,column:usize,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{if let Some(text)=row.optional_text(column)?{*destination=Some(String::new());reconstruct_text_into(destination.as_mut().unwrap(),control,text)?;}Ok(())}
fn fill_into<T>(destination:&mut Vec<T>,rows:&RowIndex<'_>,order:&[usize],owner:i64,control:&mut SqliteSnapshotControl<'_>,completed:&mut usize,value:impl Fn(FloatRow<'_>)->Result<T,ValueError>)->Result<(),ValueError>{let range=rows.range_by(order,(0,Some(owner)),control,|row|Ok((0,Some(row.integer(1)?))))?;*destination=reserve(range.len(),control)?;for position in range{destination.push(value(rows.row(order[position])?)?);tick(control,completed)?;}Ok(())}
/// 🫙️ Borrows exact numeric source words into one admitted original mesh prefix.
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioMeshSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioMeshSnapshot::SQLITE_SCHEMA,phase,control)?;let document=super::single_float_row(database,"semio_mesh_document")?;identity(document,2)?;if document.rowid!=1{return Err(invalid("invalid Semio mesh document identifier"))}
let [material_s,mesh_s,primitive_s,position_s,normal_s,uv_s,color_s,index_s,texture_s]=&mut prefix.indices;let materials=RowIndex::new(material_s,database,"semio_mesh_material",15,float_columns("semio_mesh_material"),control,"invalid Semio mesh material identity")?;let meshes=RowIndex::new(mesh_s,database,"semio_mesh_mesh",4,&[],control,"invalid Semio mesh identity")?;let primitives=RowIndex::new(primitive_s,database,"semio_mesh_primitive",6,&[],control,"invalid Semio primitive identity")?;let positions=RowIndex::new(position_s,database,"semio_mesh_position",6,float_columns("semio_mesh_position"),control,"invalid Semio position identity")?;let normals=RowIndex::new(normal_s,database,"semio_mesh_normal",6,float_columns("semio_mesh_normal"),control,"invalid Semio normal identity")?;let uvs=RowIndex::new(uv_s,database,"semio_mesh_uv",5,float_columns("semio_mesh_uv"),control,"invalid Semio UV identity")?;let colors=RowIndex::new(color_s,database,"semio_mesh_color",7,float_columns("semio_mesh_color"),control,"invalid Semio color identity")?;let indices=RowIndex::new(index_s,database,"semio_mesh_index",4,&[],control,"invalid Semio index identity")?;let textures=RowIndex::new(texture_s,database,"semio_mesh_texture",6,&[],control,"invalid Semio texture identity")?;
let [material_order,mesh_order,primitive_order,position_order,normal_order,uv_order,color_order,index_order,texture_order]=&mut prefix.orders;for(rows,order)in [(&materials,&mut *material_order),(&meshes,&mut *mesh_order),(&textures,&mut *texture_order)]{rows.ordered_into(order,2,control,"Semio mesh document ordinals require contiguous occurrences")?;for &index in rows.indices(){if rows.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio mesh document parent"))}control.checkpoint(phase,index,rows.len())?;}}
primitives.grouped_by_into(primitive_order,2,control,"Semio primitive ordinals",|row|Ok((0,Some(row.integer(1)?))))?;for &index in primitives.indices(){if meshes.get(primitives.row(index)?.integer(1)?,control)?.is_none(){return Err(invalid("dangling Semio primitive structural parent"))}control.checkpoint(phase,index,primitives.len())?;}
for(rows,order)in [(&positions,&mut *position_order),(&normals,&mut *normal_order),(&uvs,&mut *uv_order),(&colors,&mut *color_order),(&indices,&mut *index_order)]{rows.grouped_by_into(order,2,control,"Semio mesh relationship ordinals require contiguous occurrences",|row|Ok((0,Some(row.integer(1)?))))?;for &index in rows.indices(){if primitives.get(rows.row(index)?.integer(1)?,control)?.is_none(){return Err(invalid("dangling Semio mesh structural parent"))}control.checkpoint(phase,index,rows.len())?;}}
let snapshot=prefix.snapshot.as_mut().unwrap();let mut completed=0;snapshot.materials=reserve(material_order.len(),control)?;for &index in material_order.iter(){let row=materials.row(index)?;snapshot.materials.push(SemioMaterial{id:String::new(),base_color:SemioRgba{r:row.binary32(4)?,g:row.binary32(5)?,b:row.binary32(6)?,a:row.binary32(7)?},metallic:row.binary32(8)?,roughness:row.binary32(9)?,base_color_texture:None,metallic_roughness_texture:None,normal_texture:None,occlusion_texture:None,emissive_texture:None});let material=snapshot.materials.last_mut().unwrap();reconstruct_text_into(&mut material.id,control,row.text(3)?)?;for(field,column)in [(&mut material.base_color_texture,10),(&mut material.metallic_roughness_texture,11),(&mut material.normal_texture,12),(&mut material.occlusion_texture,13),(&mut material.emissive_texture,14)]{optional_into(field,row,column,control)?;}tick(control,&mut completed)?;}
snapshot.meshes=reserve(mesh_order.len(),control)?;for &index in mesh_order.iter(){let row=meshes.row(index)?;snapshot.meshes.push(SemioMesh{id:String::new(),primitives:Vec::new()});let mesh=snapshot.meshes.last_mut().unwrap();let range=primitives.range_by(primitive_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;mesh.primitives=reserve(range.len(),control)?;
for position in range{let row=primitives.row(primitive_order[position])?;let topology=match row.text(4)?{"points"=>SemioTopology::Points,"lines"=>SemioTopology::Lines,"line_strip"=>SemioTopology::LineStrip,"triangles"=>SemioTopology::Triangles,"triangle_strip"=>SemioTopology::TriangleStrip,"triangle_fan"=>SemioTopology::TriangleFan,_=>return Err(invalid("unknown Semio mesh topology"))};mesh.primitives.push(SemioPrimitive{id:String::new(),topology,positions:Vec::new(),normals:Vec::new(),uvs:Vec::new(),colors:Vec::new(),indices:Vec::new(),material_id:None});let primitive=mesh.primitives.last_mut().unwrap();
fill_into(&mut primitive.positions,&positions,position_order,row.rowid,control,&mut completed,|row|Ok(SemioPoint3{x:row.real(3)?,y:row.real(4)?,z:row.real(5)?}))?;fill_into(&mut primitive.normals,&normals,normal_order,row.rowid,control,&mut completed,|row|Ok(SemioPoint3{x:row.real(3)?,y:row.real(4)?,z:row.real(5)?}))?;fill_into(&mut primitive.uvs,&uvs,uv_order,row.rowid,control,&mut completed,|row|Ok(SemioUv{u:row.real(3)?,v:row.real(4)?}))?;fill_into(&mut primitive.colors,&colors,color_order,row.rowid,control,&mut completed,|row|Ok(SemioRgba{r:row.binary32(3)?,g:row.binary32(4)?,b:row.binary32(5)?,a:row.binary32(6)?}))?;fill_into(&mut primitive.indices,&indices,index_order,row.rowid,control,&mut completed,|row|u32::try_from(row.integer(3)?).map_err(|_|invalid("Semio mesh index exceeds unsigned word")))?;reconstruct_text_into(&mut primitive.id,control,row.text(3)?)?;optional_into(&mut primitive.material_id,row,5,control)?;tick(control,&mut completed)?;
}reconstruct_text_into(&mut mesh.id,control,row.text(3)?)?;tick(control,&mut completed)?;
}
snapshot.textures=reserve(texture_order.len(),control)?;for &index in texture_order.iter(){let row=textures.row(index)?;snapshot.textures.push(SemioTexture{id:String::new(),mime:String::new(),bytes:Vec::new()});let texture=snapshot.textures.last_mut().unwrap();reconstruct_text_into(&mut texture.id,control,row.text(3)?)?;reconstruct_text_into(&mut texture.mime,control,row.text(4)?)?;reconstruct_blob_into(&mut texture.bytes,control,row.blob(5)?)?;tick(control,&mut completed)?;}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,completed,completed)
},|prefix|prefix.snapshot.take().unwrap())}
            